  "b2.farule1": "کھاتن ہُنٛد ڈیپریسیئیشن چھُ کمپنیز ایکٹ، 2013 کِس شیڈیوٗل II مُطٲبق: پرٛتھ قسمِچ ایسیٹچ چھےٚ اکھ کارآمد عمر (مثلاً کمپیوٗٹر 3 ؤری، فرنیچر 10 ؤری، پلانٹ تہٕ مشینری 15 ؤری، کار 8 ؤری)، بچمٕژ ویلیو چھےٚ عام طور قیمتہِ ہٕنز 5% کھۄتہٕ زیادٕ نہٕ آسان، تہٕ ؤرِیس منٛز جوڑنہٕ یا کُننہٕ آمٕتِس ایسیٹس پیٹھ چھُ صرف استعمال کٔرِمٕتین دۄہن ہُنٛد ڈیپریسیئیشن لگان۔ اسٹریٹ لائن (SLM: پرٛتھ ؤری برابر رقم) یا رِٹن ڈاؤن ویلیو (WDV: بچمٕژ رقمہِ پیٹھ مقرر ریٹ) ژارِو۔ پروپرائٹر تہٕ فرم چھِ اکثر یہُے طریقہٕ ورتاوان؛ فیصلہٕ چھُ توٚہنٛد اکاؤنٹنٹ کران۔",
  "b2.farule2": "انکم ٹیکس ڈیپریسیئیشن چھُ پرٛتھ بلاکُک الگ کڈنہٕ یِوان: بلاک ریٹس پیٹھ رِٹن ڈاؤن ویلیو (مثلاً پلانٹ تہٕ مشینری 15%، فرنیچر 10%، کمپیوٗٹر 40%)، ؤرِیس منٛز 180 دۄہن کھۄتہٕ کم استعمال گوٚمتِس ایسیٹس پیٹھ اَڈٕ ریٹ، تہٕ بِکری ہٕنزٕ پونٛسہٕ چھِ بلاکہٕ منٛزٕ کم گژھان۔ یہِ چھُ صرف انکم ٹیکس ریٹرنہٕ خٲطرٕ، کھاتس منٛز چھُ نہٕ زانٛہہ ترٛاونہٕ یِوان۔ بٔرِتھ ریٹ چھِ عام بلاک ریٹ: پنٛنِس اکاؤنٹنٹس سٟتۍ کٔرِو پَکہٕ، خاص کر 1 اپریل 2026 پیٚٹھٕ انکم ٹیکس ایکٹ، 2025 تحت ؤرین خٲطرٕ۔",
  "b2.farule3": "ڈیپریسیئیشن چھُ توٚہنٛدِس کھاتس منٛز تیلہِ گژھان ییلہِ توٚہۍ 'ڈیپریسیئیشن ترٛٲوِو' دباوِو: ؤرِیُک آخری دۄہ (یا ؤرِیس منٛز اَز) کِس تاریخس پیٹھ جرنل اینٹری چھےٚ ڈیپریسیئیشن ڈیبٹ کران تہٕ پرٛتھ ایسیٹ کم کران۔ پتہٕ ایسیٹ بدلٲوِو تہٕ دوبارٕ ترٛٲوِو، صرف فرق جُڑِ۔",
